using Dhole.Content.Domain.Navigation.Entities;using Microsoft.EntityFrameworkCore;using Microsoft.EntityFrameworkCore.Metadata.Builders;namespace Dhole.Content.Persistence.Configurations.Navigation;internal sealed class NavigationMenuItemConfiguration:IEntityTypeConfiguration<NavigationMenuItem>{public void Configure(EntityTypeBuilder<NavigationMenuItem>b){b.ToTable("navigation_menu_items");b.HasKey(x=>x.Id);b.Property(x=>x.Id).ValueGeneratedNever();b.Property(x=>x.Label).HasMaxLength(200).IsRequired();b.Property(x=>x.Url).HasMaxLength(1200);b.Property(x=>x.Target).HasMaxLength(20).IsRequired();b.HasIndex(x=>new{x.MenuId,x.SortOrder});}}
